#include <iostream>
#include <queue>
#include <cctype>
#include <vector>
#include <cstring>
#include <climits>
using namespace std;

const int INF = 12345678;

struct Node {
    int i, j, no;
};

struct Container {
    int no[1000];
    int ind;
    int fl;
};

Container caps[100][100];
vector<int> adj[1000];
int n, t;
int leftMatch[1000], rightMatch[1000], color[1000];
char grid[1000][1000], grid1[1000][1000];
int dist[1000][1000], dist1[1000][1000];
queue<Node> bfsQueue;

void bfsFromZ(Node start);
void bfsFromDigit(Node start);
int maximumMatching(int nodeCount);
bool augmentPath(int node);

int main() {
    int i, j, k, l;
    Node temp, temp1;

    scanf("%d %d", &n, &t);

    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            dist[i][j] = INF;
        }
    }

    for (i = 0; i < n; i++) {
        scanf("%s", grid[i]);
    }

    for (i = 0; i < n; i++) {
        scanf("%s", grid1[i]);
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (grid[i][j] == 'Z') {
                temp.i = i;
                temp.j = j;
                bfsFromZ(temp);
            }
        }
    }

    int marker = 1;

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(grid1[i][j])) {
                k = grid1[i][j] - '0';
                if (k > 0) caps[i][j].fl = 1;
                caps[i][j].ind = k;
                for (l = 1; l <= k; l++) {
                    caps[i][j].no[l] = marker++;
                }
            }
        }
    }

    marker = 1;

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(grid[i][j])) {
                k = grid[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    temp.i = i;
                    temp.j = j;
                    temp.no = marker++;
                    bfsFromDigit(temp);
                }
            }
        }
    }

    printf("%d\n", maximumMatching(marker - 1));

    return 0;
}

bool augmentPath(int node) {
    if (color[node]) return false;
    color[node] = 1;

    for (int i = 0; i < adj[node].size(); i++) {
        int neighbor = adj[node][i];
        if (leftMatch[neighbor] == -1) {
            leftMatch[neighbor] = node;
            rightMatch[node] = i;
            return true;
        } else if (augmentPath(leftMatch[neighbor])) {
            leftMatch[neighbor] = node;
            rightMatch[node] = i;
            return true;
        }
    }

    return false;
}

int maximumMatching(int nodeCount) {
    memset(leftMatch, -1, sizeof(leftMatch));
    memset(rightMatch, -1, sizeof(rightMatch));
    bool changed;

    do {
        changed = true;
        memset(color, 0, sizeof(color));

        for (int i = 1; i <= nodeCount; i++) {
            if (rightMatch[i] == -1 && augmentPath(i)) {
                changed = false;
            }
        }
    } while (!changed);

    int count = 0;
    for (int i = 1; i <= nodeCount; i++) {
        if (rightMatch[i] != -1) count++;
    }

    return count;
}

void bfsFromDigit(Node start) {
    int i, j, k, l;
    Node temp, temp1;

    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            dist1[i][j] = INF;
        }
    }

    i = start.i;
    j = start.j;
    dist1[i][j] = 0;
    bfsQueue.push(start);

    while (!bfsQueue.empty()) {
        temp = bfsQueue.front();
        bfsQueue.pop();
        i = temp.i;
        j = temp.j;

        if (dist1[i][j] > t) continue;
        if (grid[i][j] == 'Y') continue;

        if (caps[i][j].fl == 1) {
            if (dist1[i][j] <= t && dist1[i][j] <= dist[i][j]) {
                for (k = 1; k <= caps[i][j].ind; k++) {
                    adj[start.no].push_back(caps[i][j].no[k]);
                }
            }
        }

        if (dist1[i][j] >= dist[i][j]) continue;

        k = i + 1;
        l = j;
        if (k < n && dist1[k][l] > dist1[i][j] + 1) {
            dist1[k][l] = dist1[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i - 1;
        l = j;
        if (k >= 0 && dist1[k][l] > dist1[i][j] + 1) {
            dist1[k][l] = dist1[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i;
        l = j + 1;
        if (l < n && dist1[k][l] > dist1[i][j] + 1) {
            dist1[k][l] = dist1[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i;
        l = j - 1;
        if (l >= 0 && dist1[k][l] > dist1[i][j] + 1) {
            dist1[k][l] = dist1[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }
    }
}

void bfsFromZ(Node start) {
    int i, j, k, l;
    Node temp, temp1;
    i = start.i;
    j = start.j;
    dist[i][j] = 0;
    bfsQueue.push(start);

    while (!bfsQueue.empty()) {
        temp = bfsQueue.front();
        bfsQueue.pop();
        i = temp.i;
        j = temp.j;

        if (grid[i][j] == 'Y') continue;

        k = i + 1;
        l = j;
        if (k < n && dist[k][l] > dist[i][j] + 1) {
            dist[k][l] = dist[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i - 1;
        l = j;
        if (k >= 0 && dist[k][l] > dist[i][j] + 1) {
            dist[k][l] = dist[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i;
        l = j + 1;
        if (l < n && dist[k][l] > dist[i][j] + 1) {
            dist[k][l] = dist[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }

        k = i;
        l = j - 1;
        if (l >= 0 && dist[k][l] > dist[i][j] + 1) {
            dist[k][l] = dist[i][j] + 1;
            temp1.i = k;
            temp1.j = l;
            bfsQueue.push(temp1);
        }
    }
}
